// Conceptual Kubernetes Controller Reconciliation Loop
func (r *DeploymentReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    // 1. Fetch desired state from API server cache
    deployment := &apps.Deployment{}
    if err := r.Get(ctx, req.NamespacedName, deployment); err != nil {
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }

    // 2. Fetch actual state (matching pods currently running in cluster)
    actualPods := &core.PodList{}
    r.List(ctx, actualPods, client.InNamespace(req.Namespace), client.MatchingLabels(deployment.Spec.Selector.MatchLabels))

    // 3. Level-Triggered Convergence: Actual vs Desired
    diff := deployment.Spec.Replicas - len(actualPods.Items)
    if diff > 0 {
        r.scaleUp(diff)
    } else if diff < 0 {
        r.scaleDown(-diff)
    }

    return ctrl.Result{}, nil // Reconciled successfully!
}

// kube-apiserver Pipeline Stages:
// [ HTTP Request: POST /api/v1/namespaces/default/pods ]
//       |
//       v 1. Authentication (X.509 cert, Bearer token, OIDC)
//       v 2. Authorization (RBAC: Can user 'X' create pods in 'default'?)
//       v 3. Mutating Webhooks (Inject Envoy sidecar, apply default CPU limits)
//       v 4. Object Schema Validation (Enforce OpenAPI types)
//       v 5. Validating Webhooks (Reject if container runs as root / lacks team label)
//       |
//       v 6. etcd Write: Key '/registry/pods/default/my-pod' written with revision!

// Topology Comparison:
// 1. Stacked HA Topology (3 Nodes):
// [ Master 1: apiserver + etcd-1 ] <-// [ Master 2: apiserver + etcd-2 ] <--> (Raft Sync over local/private network)
// [ Master 3: apiserver + etcd-3 ] <-/

// 2. External etcd HA Topology (6 Nodes - Enterprise Gold Standard):
// [ Control Plane 1: apiserver ]  [ Control Plane 2 ]  [ Control Plane 3 ]
//                                        |                       /
//                  v                      v                      v
//              [ etcd Node 1 ] <---> [ etcd Node 2 ] <---> [ etcd Node 3 ]

// CSI RPC Call Flow during Pod Startup:
// 1. PVC Created -> CSI Controller: CreateVolume() -> Creates AWS EBS Volume
// 2. Pod Scheduled on Node-01 -> CSI Controller: ControllerPublishVolume() -> Attaches EBS to EC2 Node-01
// 3. Kubelet on Node-01 -> CSI Node Plugin: NodeStageVolume() -> Formats disk (mkfs.ext4)
// 4. Kubelet on Node-01 -> CSI Node Plugin: NodePublishVolume() -> Mounts disk to /var/lib/kubelet/pods/...
// 5. Container Starts -> Container rootfs mounts volume at target path!

// Storage Backend Access Mode Matrix:
// - AWS EBS / GCP PD / Azure Disk: ReadWriteOnce (Block Storage)
// - AWS EFS / Azure Files / NFS / CephFS: ReadWriteMany (File Storage)
// - S3 / Object Stores (CSI): ReadOnlyMany (Object Storage)
// - Dedicated Database (Postgres): ReadWriteOncePod (Strict Pod Isolation)

// The Kubernetes Networking Invariant:
// Pod A (IP: 10.244.1.15) on Node 1 connects to Pod B (IP: 10.244.2.40) on Node 2
// - Source IP received by Pod B: 10.244.1.15 (NO SNAT!)
// - Destination IP sent by Pod A: 10.244.2.40 (NO DNAT!)
// Handled seamlessly by CNI plugins (Calico, Cilium, AWS VPC CNI) via routing or encapsulation.

// CNI Feature Comparison Matrix:
// Feature               | Flannel    | Calico          | Cilium
// -----------------------------------------------------------------
// Network Policies      | NO         | YES (Layer 3/4) | YES (Layer 3/4/7)
// Implementation        | VXLAN      | BGP / IPIP      | eBPF Socket / XDP
// Kube-Proxy Replace    | NO         | NO              | YES (Full eBPF)
// Observability         | None       | Felix Metrics   | Hubble Service Map
// Encrypted Tunnels     | WireGuard  | WireGuard       | WireGuard / IPsec

// Overlay vs Flat Routing Packet Flow:
// 1. Overlay (VXLAN):
// [ Outer IP: Node-1 -> Node-2 ][ UDP: 4789 ][ Inner IP: Pod-A -> Pod-B ][ Payload ]
// (Requires MTU reduction and CPU encapsulation/decapsulation cycles)

// 2. Flat Routed (AWS VPC CNI / Calico BGP):
// [ IP: Pod-A -> Pod-B ][ TCP: 8080 ][ Payload ]
// (Standard 1500 or 9001 Jumbo frames, zero packet overhead, native VPC peering)

// Service Mesh Topology Comparison:
// 1. Classic Sidecar Mesh (Istio Envoy):
// [ Pod: App + Envoy (100MB) ] <--- mTLS ---> [ Pod: DB + Envoy (100MB) ]
// (Memory scales linearly with pod count!)

// 2. Ambient Sidecarless Mesh (Istio Ambient / Cilium):
// [ Pod: App ]                                 [ Pod: DB ]
//      |                                            |
//   (eBPF)                                       (eBPF)
//      v                                            v
// [ Node zTunnel DaemonSet (Layer 4 mTLS) ] <---> [ Node zTunnel DaemonSet ]

// Conceptual Scheduling Pipeline Execution:
// [ Unscheduled Pod ] -> PreFilter -> Filter (Drops 15 nodes) -> 5 Feasible Nodes
// -> PreScore -> Score (Ranks Node-02 highest with 94/100 points)
// -> Reserve (Locks resources in scheduler cache)
// -> Permit (Checks gang scheduling barriers)
// -> PreBind -> Bind (POST /api/v1/namespaces/default/pods/my-pod/binding -> Node-02)

// QoS Derivation Rules:
// 1. Guaranteed:
//    requests: { cpu: "1", memory: "1Gi" }
//    limits:   { cpu: "1", memory: "1Gi" }  <-- Requests EQUAL Limits!
//
// 2. Burstable:
//    requests: { cpu: "500m", memory: "512Mi" }
//    limits:   { cpu: "2",    memory: "2Gi" }    <-- Requests LESS THAN Limits!
//
// 3. BestEffort:
//    resources: {}  <-- No requests or limits specified!

// Safe Architecture: Decoupled Multi-Dimensional Autoscaling
// 1. Horizontal Pod Autoscaler:
//    - Metric: External Kafka Consumer Group Lag (or HTTP RPS)
//    - Action: Scales pod replica count from 5 to 50
//
// 2. Vertical Pod Autoscaler:
//    - Metric: Observed CPU / Memory usage
//    - updatePolicy: Off (Generates recommendations for CI/CD updates without racing!)

// Conceptual Go Controller Reconciliation Loop
func (r *PostgresClusterReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    // 1. Fetch current desired state from API Server
    var cluster dbv1.PostgresCluster
    if err := r.Get(ctx, req.NamespacedName, &cluster); err != nil {
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }

    // 2. Observe underlying child resources (StatefulSets, Services)
    var sts appsv1.StatefulSet
    err := r.Get(ctx, req.NamespacedName, &sts)
    if errors.IsNotFound(err) {
        // 3. Act: StatefulSet missing -> Create desired StatefulSet
        newSts := r.buildStatefulSet(&cluster)
        return ctrl.Result{}, r.Create(ctx, newSts)
    }

    // 4. Update Status subresource with observed healthy replica count
    cluster.Status.ReadyReplicas = sts.Status.ReadyReplicas
    return ctrl.Result{}, r.Status().Update(ctx, &cluster)
}

// Kubebuilder / Controller-Runtime Setup
func main() {
    mgr, err := ctrl.NewManager(ctrl.GetConfigOrDie(), ctrl.Options{
        Scheme: scheme,
        MetricsBindAddress: ":8080",
        LeaderElection: true,
        LeaderElectionID: "my-operator-lock",
    })
    if err != nil { os.Exit(1) }

    // Register Reconciler watching Custom Resource
    if err = (&controllers.AppClusterReconciler{
        Client: mgr.GetClient(), // Reads from Informer Cache, writes to API
        Scheme: mgr.GetScheme(),
    }).SetupWithManager(mgr); err != nil {
        os.Exit(1)
    }

    if err := mgr.Start(ctrl.SetupSignalHandler()); err != nil {
        os.Exit(1)
    }
}

